'use client'

import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  useState,
  type ButtonHTMLAttributes,
} from 'react'
import { cn } from '@/lib/utils'
import { playHoverSound, playClickSound } from '@/lib/sound'

const KEYFRAME_STYLE_ID = '__clipboard_field_kf__'

function ensureKeyframes() {
  if (typeof document === 'undefined') return
  if (document.getElementById(KEYFRAME_STYLE_ID)) return
  const style = document.createElement('style')
  style.id = KEYFRAME_STYLE_ID
  style.textContent = `
    @keyframes cf-fade-out {
      from { opacity: 1; transform: scale(1); }
      to   { opacity: 0; transform: scale(0.97); }
    }
    @keyframes cf-fade-in {
      from { opacity: 0; transform: scale(0.97); }
      to   { opacity: 1; transform: scale(1); }
    }
    @keyframes cf-icon-exit {
      from { opacity: 1; transform: scale(1) rotate(0deg); }
      to   { opacity: 0; transform: scale(0.7) rotate(-8deg); }
    }
    @keyframes cf-icon-enter {
      from { opacity: 0; transform: scale(0.7) rotate(8deg); }
      to   { opacity: 1; transform: scale(1) rotate(0deg); }
    }
  `
  document.head.appendChild(style)
}

export interface ClipboardFieldProps extends Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  'children' | 'onCopy' | 'value'
> {
  value: string
  prompt?: string
  copiedLabel?: string
  copyLabel?: string
  resetDelay?: number
  onCopy?: () => void
  hideIcon?: boolean
}

function CopyIcon({ className }: { className?: string }) {
  return (
    <svg
      width={14}
      height={14}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <rect x="9" y="9" width="12" height="12" rx="2" />
      <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
    </svg>
  )
}

function CheckIcon({ className }: { className?: string }) {
  return (
    <svg
      width={14}
      height={14}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <path d="M20 6 9 17l-5-5" />
    </svg>
  )
}

export const ClipboardField = forwardRef<HTMLButtonElement, ClipboardFieldProps>(
  (
    {
      value,
      prompt = '$',
      copiedLabel = 'Copied to clipboard',
      copyLabel = 'Copy to clipboard',
      resetDelay = 2000,
      onCopy,
      hideIcon = false,
      disabled,
      className,
      onClick,
      type = 'button',
      ...props
    },
    ref,
  ) => {
    const [copied, setCopied] = useState(false)
    const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

    useEffect(() => {
      ensureKeyframes()
    }, [])

    useEffect(
      () => () => {
        if (resetTimer.current) clearTimeout(resetTimer.current)
      },
      [],
    )

    const handleCopy = useCallback(async () => {
      if (disabled) return
      playClickSound()
      try {
        await navigator.clipboard.writeText(value)
        setCopied(true)
        onCopy?.()
        if (resetTimer.current) clearTimeout(resetTimer.current)
        resetTimer.current = setTimeout(() => setCopied(false), resetDelay)
      } catch {}
    }, [disabled, value, onCopy, resetDelay])

    return (
      <button
        ref={ref}
        type={type}
        disabled={disabled}
        data-copied={copied ? '' : undefined}
        aria-label={copied ? copiedLabel : copyLabel}
        onClick={(e) => {
          onClick?.(e)
          if (!e.defaultPrevented) void handleCopy()
        }}
        onMouseEnter={() => playHoverSound()}
        onPointerDown={(e) => {
          e.preventDefault()
        }}
        className={cn(
          'clipboard-field group relative inline-grid max-w-full cursor-pointer items-center gap-x-2',
          'rounded-md border border-(--color-border) bg-(--color-surface-2)',
          'px-3 py-2.5 font-mono text-[13px] leading-none text-(--color-fg)',
          'outline-none select-none',
          hideIcon ? 'grid-cols-[auto_1fr]' : 'grid-cols-[auto_1fr_auto]',
          'transition-[border-color,background-color] duration-(--motion-dur-fast) ease-(--motion-ease-in-out) motion-reduce:transition-none',
          'hover:border-(--color-border-strong) hover:bg-(--color-surface)',
          'focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-1 focus-visible:ring-offset-(--color-bg)',
          'active:scale-[0.98] motion-reduce:active:scale-100',
          'disabled:pointer-events-none disabled:opacity-50',
          className,
        )}
        {...props}
      >
        <span
          aria-hidden="true"
          className="col-start-1 row-start-1 text-(--color-muted) tabular-nums"
        >
          {prompt}
        </span>

        {/* Both layers share col 2, crossfade only, button width never changes. */}
        <span
          data-slot="command"
          style={{
            willChange: 'opacity, transform',
            animation: copied
              ? 'cf-fade-out 0.18s var(--motion-ease-in-out) forwards'
              : 'cf-fade-in 0.14s var(--motion-ease-out) forwards',
          }}
          className={cn(
            'col-start-2 row-start-1 min-w-0 overflow-hidden whitespace-nowrap text-start text-(--color-muted)',
            'pointer-events-none',
            'motion-reduce:[animation:none]',
          )}
        >
          {value}
        </span>

        <span
          data-slot="copied"
          aria-hidden={!copied}
          style={{
            willChange: 'opacity, transform',
            animation: copied
              ? 'cf-fade-in 0.18s 40ms var(--motion-ease-out) both'
              : 'cf-fade-out 0.1s var(--motion-ease-in-out) both',
          }}
          className={cn(
            'col-start-2 row-start-1 min-w-0 overflow-hidden whitespace-nowrap text-start text-(--color-fg)',
            'motion-reduce:[animation:none] motion-reduce:opacity-0',
          )}
        >
          {copiedLabel}
        </span>

        {!hideIcon && (
          <span
            aria-hidden="true"
            className="relative col-start-3 row-start-1 size-4 shrink-0 text-(--color-muted) transition-colors duration-(--motion-dur-fast) group-hover:text-(--color-fg) group-data-[copied]:text-(--color-fg)"
          >
            <span
              style={{
                willChange: 'opacity, transform',
                animation: copied
                  ? 'cf-icon-exit 0.08s var(--motion-ease-in-out) forwards'
                  : 'cf-icon-enter 0.12s var(--motion-ease-out) forwards',
              }}
              className="absolute inset-0 flex items-center justify-center motion-reduce:[animation:none]"
            >
              <CopyIcon />
            </span>
            <span
              style={{
                willChange: 'opacity, transform',
                animation: copied
                  ? 'cf-icon-enter 0.12s 40ms var(--motion-ease-out) both'
                  : 'cf-icon-exit 0.06s var(--motion-ease-in-out) both',
              }}
              className="absolute inset-0 flex items-center justify-center motion-reduce:[animation:none] motion-reduce:opacity-0"
            >
              <CheckIcon />
            </span>
          </span>
        )}
      </button>
    )
  },
)

ClipboardField.displayName = 'ClipboardField'

export function ClipboardFieldPreview() {
  return (
    <div className="flex w-full items-center justify-center p-6">
      <ClipboardField value="npx shadcn@latest add @nexvyn/badge" className="w-full max-w-md" />
    </div>
  )
}

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playTileNote(frequency = 440, volume = 0.08) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime
    const dur = 1.1

    const osc = ctx.createOscillator()
    const shimmer = ctx.createOscillator()
    const shimmerGain = ctx.createGain()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(frequency, now)
    shimmer.type = 'sine'
    shimmer.frequency.setValueAtTime(frequency * 2, now)

    shimmerGain.gain.setValueAtTime(0.22, now)
    shimmerGain.gain.exponentialRampToValueAtTime(0.0001, now + dur * 0.5)

    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.015)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur)

    shimmer.connect(shimmerGain)
    shimmerGain.connect(gain)
    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + dur)
    shimmer.start(now)
    shimmer.stop(now + dur)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
